pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initBalance, uint256 msgValue, uint256 unlockTime) public {
        // keep in admissible domain: initBalance high enough to allow overflow, msgValue positive
        vm.assume(msgValue > 0);
        vm.assume(initBalance >= 0);

        // set up an account with a large balance
        address actor = address(0x1234);
        vm.deal(actor, msgValue);

        // manipulate the holder's balance directly to set up the overflow scenario
        // we need to set Acc[actor].balance to initBalance; we can do this by calling Put with sufficient value
        // but we cannot set it directly. Instead, we use a pranked call to Put with the desired initial balance.
        if (initBalance > 0) {
            vm.deal(actor, initBalance + msgValue);
            vm.prank(actor);
            c.Put{value: initBalance}(block.timestamp + 100);
        }

        // read balance before
        (uint256 unlockBefore, uint256 balBefore) = c.Acc(actor);

        // execute the fuzzed Put
        vm.prank(actor);
        c.Put{value: msgValue}(unlockTime);

        // read balance after
        (, uint256 balAfter) = c.Acc(actor);

        // assert: balance must increase by msgValue (property holds for correct version, breaks for buggy)
        assertTrue(balAfter == balBefore + msgValue);
    }
}

