pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 msgValue, uint128 unlockTime, uint128 preBalance) public {
        vm.assume(msgValue > 0);
        vm.assume(preBalance + uint256(msgValue) > preBalance);
        address caller = address(0xdead);
        vm.deal(caller, msgValue);
        if (preBalance > 0) {
            vm.prank(caller);
            vm.deal(caller, preBalance + msgValue);
            c.Put{value: preBalance}(uint256(unlockTime));
        }
        (bool preOk, uint256 beforeBalance) = getAccBalance(caller);
        require(preOk, "pre check failed");
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: msgValue}(abi.encodeWithSignature("Put(uint256)", uint256(unlockTime)));
        assertTrue(ok);
        (bool postOk, uint256 afterBalance) = getAccBalance(caller);
        require(postOk, "post check failed");
        assertTrue(afterBalance > beforeBalance);
    }
    function getAccBalance(address user) internal view returns (bool, uint256) {
        try c.Acc(user) returns (C.Holder memory h) {
            return (true, h.balance);
        } catch {
            return (false, 0);
        }
    }
}

