pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 depositAmount, uint256 collectAmount, uint256 futureWarp) public {
        // Restrict to admissible domain: deposit must fit, _unlockTime wide enough,
        // collect amount <= deposit, and futureWarp is a time after deposit but before _unlockTime.
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(depositAmount >= collectAmount);
        vm.assume(_unlockTime > block.timestamp);
        vm.assume(futureWarp > block.timestamp);
        vm.assume(futureWarp < _unlockTime);

        // Set up the caller
        address caller = address(0x1234);
        vm.deal(caller, depositAmount);

        // Put: send deposit with an _unlockTime in the future
        vm.prank(caller);
        c.Put{value: depositAmount}(_unlockTime);

        // Warp to a time after deposit but before the specified unlockTime
        vm.warp(futureWarp);

        // Try to Collect: in the original this should FAIL because unlockTime hasn't been reached;
        // in the mutant unlockTime is block.timestamp of the Put, which is in the past now,
        // so Collect succeeds (stealing from the future lock).
        bool ok;
        vm.prank(caller);
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract must NOT allow early collect (ok == false).
        // Any violation means the mutant behaviour was observed.
        assertTrue(ok == false);
    }
}

