pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint56 amount, bool collectBefore) public {
        // Ensure unlockTime is strictly in the future
        vm.assume(_unlockTime > block.timestamp);
        vm.assume(_unlockTime < type(uint256).max - 1000);
        // Ensure amount is enough to meet MinSum
        vm.assume(amount >= 1 ether);
        address actor = address(uint160(uint256(keccak256(abi.encode(uint256(1122))))));
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(_unlockTime);
        // Decide whether to attempt collect before unlockTime
        if (collectBefore) {
            vm.warp(block.timestamp + 1); // still before unlockTime
        } else {
            vm.warp(_unlockTime + 1);
        }
        vm.prank(actor);
        bool ok = true;
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        if (collectBefore) {
            // If attempting before unlockTime, must revert
            assertTrue(!ok, "Collect before unlockTime should revert");
        } else {
            // If attempting after unlockTime, must succeed (reference behavior)
            assertTrue(ok, "Collect after unlockTime should succeed");
        }
    }
