import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 value, uint256 unlockTime) public {
        vm.assume(value > 0);
        address sender = address(0x1234);
        vm.deal(sender, value);
        uint256 sumBefore = sumAllAccBalances();
        vm.prank(sender);
        c.Put{value: value}(unlockTime);
