import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 collectAmt, uint256 putAmt) public {
        // Admissible domain: positive amounts, collectAmt <= balance, and MinSum is 1 ether
        vm.assume(putAmt > 0 && putAmt >= 1 ether);
        vm.assume(collectAmt > 0 && collectAmt <= putAmt);
        // Collect should succeed only when block.timestamp > unlockTime.
        // We fuzz unlockTime in the past/future relative to block.timestamp.
        // Bound unlockTime to avoid overflow and keep wide.
        vm.assume(unlockTime <= type(uint64).max);

        // Setup: fund this contract and deposit
        vm.deal(address(this), putAmt);
        c.Put{value: putAmt}(unlockTime);

        // Warp to a timestamp strictly after now (or before) to test the property.
        // To keep the fuzzer searching freely, we let it choose a warpTs relative to unlockTime.
        // We bound warpTs to a sensible range.
        uint256 warpTs = block.timestamp + 1; // warp after current, but we need to make the condition depend on unlockTime
        // Actually, we need to warp to a timestamp that may be before or after unlockTime.
        // The rule: if block.timestamp <= acc.unlockTime, Collect MUST revert.
        // We warp to a value that is <= unlockTime to trigger the revert expectation.
        // But the fuzzer can set unlockTime arbitrarily, so we need to guarantee
        // that block.timestamp <= unlockTime for some runs. We'll use vm.warp to a timestamp
        // that is strictly less than unlockTime when unlockTime is large enough.
        // However, vm.warp must be called with a value >= block.timestamp (Foundry restriction).
        // To overcome this, we can only warp forward. So we set unlockTime to a future time
        // and then try Collect without warping, meaning block.timestamp <= unlockTime.
        // The fuzzer will naturally produce unlockTime > block.timestamp.
        // For the case where unlockTime is in the past, the original will succeed and the bug will too.
        // The difference is when block.timestamp <= unlockTime: original reverts, bug succeeds.
        // We just need to ensure that for some fuzzed inputs, block.timestamp <= unlockTime.
        // Since unlockTime is fuzzed, it can be > block.timestamp, and we don't warp.
        // So the test: after Put, call Collect. The original must revert if block.timestamp <= unlockTime.
        // But the assertion must be a general rule that holds for ALL inputs.
        // Rule: if block.timestamp <= acc.unlockTime, Collect reverts.
        // We can assert: (Collect reverts) == (block.timestamp <= acc.unlockTime).
        // However, the reference never reverts when block.timestamp > unlockTime (provided balance and MinSum are met).
        // So the invariant is: Collect does not revert iff block.timestamp > acc.unlockTime (and balance >= _am >= MinSum).
        // We'll assert: the revert status of Collect equals (block.timestamp <= acc.unlockTime).
        // But balance conditions also apply. We only call Collect when balance >= _am and _am >= MinSum.
        // We ensure that. Then the only varying condition is unlockTime vs timestamp.

        // Get current unlockTime
        (uint storedUnlockTime, uint balance) = c.Acc(address(this));
        require(balance >= collectAmt, "balance insufficient");

        bool success;
        try c.Collect(collectAmt) { success = true; } catch { success = false; }

        // The rule: success == (block.timestamp > storedUnlockTime)
        // Because the original requires block.timestamp > acc.unlockTime to succeed,
        // while the buggy version does not.
        bool expectedSuccess = block.timestamp > storedUnlockTime;
        assertTrue(success == expectedSuccess);
    }
}

